from __future__ import annotations

import re
import socket
from datetime import datetime
from typing import Callable, Optional

from secretscan.config import Config
from secretscan.model import (
    Confidence,
    Finding,
    Module,
    ModuleStatus,
    RunMeta,
    RunResult,
    Severity,
)
from secretscan.rules.loader import load_default_rules, load_rules_file
from secretscan.rules.rule import CompiledRule


def _dedup(findings: list[Finding]) -> list[Finding]:
    by_key: dict[tuple[str, str], Finding] = {}
    order: list[tuple[str, str]] = []

    for f in findings:
        key = (f.location, f.secret_hash)
        if key not in by_key:
            by_key[key] = f
            order.append(key)
        else:
            existing = by_key[key]
            if f.severity.rank() > existing.severity.rank():
                also = [existing.rule_id] + existing.also_matched + f.also_matched
                f.also_matched = also
                by_key[key] = f
            else:
                existing.also_matched.append(f.rule_id)

    return [by_key[k] for k in order]


def _group_by_value(findings: list[Finding]) -> list[Finding]:
    groups: dict[tuple[str, str], list[Finding]] = {}
    order: list[tuple[str, str]] = []

    for f in findings:
        key = (f.rule_id, f.secret_hash)
        if key not in groups:
            order.append(key)
            groups[key] = []
        groups[key].append(f)

    result: list[Finding] = []
    for key in order:
        members = groups[key]
        members.sort(key=lambda f: f.file_path)
        rep = members[0]
        extra = sorted({m.file_path for m in members[1:] if m.file_path and m.file_path != rep.file_path})
        if extra:
            rep.additional_files = extra
        result.append(rep)
    return result


def _filter_severity_confidence(
    findings: list[Finding],
    min_severity: Severity,
    min_confidence: Confidence,
) -> list[Finding]:
    return [
        f for f in findings
        if f.severity.rank() >= min_severity.rank()
        and f.confidence.rank() >= min_confidence.rank()
    ]


def _severity_counts(findings: list[Finding]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for f in findings:
        counts[f.severity.value] = counts.get(f.severity.value, 0) + 1
    return counts


def sort_findings(findings: list[Finding]) -> None:
    findings.sort(key=lambda f: (-f.severity.rank(), f.file_path, f.location))


def run_scan(
    cfg: Config,
    progress: Optional[Callable[[int, int], None]] = None,
) -> RunResult:
    from secretscan.scanner.chrome import chrome_scan
    from secretscan.scanner.docker import docker_scan
    from secretscan.scanner.filesystem import filesystem_scan
    from secretscan.scanner.internet import check_internet
    from secretscan.scanner.keychain import keychain_scan
    from secretscan.scanner.lan import lan_scan
    from secretscan.scanner.network import network_scan
    from secretscan.scanner.process_env import process_env_scan
    from secretscan.scanner.shell_history import shell_history_scan
    from secretscan.scanner.tools import tools_scan

    started = datetime.utcnow()

    if cfg.rules_file:
        rules = load_rules_file(cfg.rules_file)
    else:
        rules = load_default_rules()

    allow_patterns: list[re.Pattern] = []
    allow_matcher: Callable[[str], bool] | None = None
    if allow_patterns:
        def allow_matcher(val: str) -> bool:
            return any(p.search(val) for p in allow_patterns)

    raw: list[Finding] = []
    statuses: list[ModuleStatus] = []
    meta = RunMeta(
        started_at=started,
        paths=cfg.paths,
        modules=cfg.modules,
    )

    total = len(cfg.modules)
    for i, mod in enumerate(cfg.modules):
        if mod == Module.FILESYSTEM:
            st = filesystem_scan(cfg, rules, raw.append, allow_matcher)
            statuses.append(st)

        elif mod == Module.SHELL_HISTORY:
            st = shell_history_scan(rules, raw.append, cfg.reveal_length, allow_matcher)
            statuses.append(st)

        elif mod == Module.KEYCHAIN:
            st = keychain_scan(raw.append)
            statuses.append(st)

        elif mod == Module.PROCESS_ENV:
            st = process_env_scan(rules, raw.append, cfg.reveal_length, allow_matcher)
            statuses.append(st)

        elif mod == Module.INSTALLED_TOOLS:
            tools, st = tools_scan()
            meta.tools = tools
            statuses.append(st)

        elif mod == Module.NETWORK:
            listeners, st = network_scan()
            meta.listeners = listeners
            statuses.append(st)

        elif mod == Module.DOCKER:
            docker_status, st = docker_scan()
            meta.docker = docker_status
            statuses.append(st)

        elif mod == Module.CHROME:
            chrome_status, st = chrome_scan(cfg.output_dir)
            meta.chrome = chrome_status
            statuses.append(st)

        elif mod == Module.LAN:
            devices, interfaces, st = lan_scan()
            meta.lan_devices = devices
            meta.interfaces = interfaces
            statuses.append(st)

        elif mod == Module.INTERNET:
            internet_status, st = check_internet()
            meta.internet = internet_status
            statuses.append(st)

        if progress:
            progress(i + 1, total)

    deduped = _dedup(raw)
    deduped = _group_by_value(deduped)
    deduped = _filter_severity_confidence(deduped, cfg.min_severity, cfg.min_confidence)
    sort_findings(deduped)

    meta.finished_at = datetime.utcnow()
    meta.module_statuses = statuses
    meta.severity_counts = _severity_counts(deduped)

    return RunResult(findings=deduped, meta=meta)
